const rel = p => p.replace(ROOT + '/', '').replace('node_modules/@salesforce/retail-react-app/app/', 'BASE:').replace('overrides/app/', 'OVR:');
console.log(`Modules reachable from PDP entry: ${graph.size}`);
console.log(`Entry: ${rel(entry)}\n`);
if (!cycles.length) { console.log('No cycles reachable from the PDP entry.'); }
else {
